for(const width of [1280,390])test(`Browse files is a subtle link before Upload and opens the file view at ${width}px`,async({page,context})=>{
 await page.setViewportSize({width,height:900});await fixture(page,context);await page.goto(`${origin}/games/test-game/assets`);const library=page.getByRole('region',{name:'Assets',exact:true}),link=page.getByRole('link',{name:'Browse files',exact:true});await expect(link).toBeVisible();await expect(link).toBeInViewport();const box=await link.boundingBox(),region=await library.boundingBox(),uploadBox=await page.getByRole('button',{name:'Upload',exact:true}).boundingBox(),generateBox=await page.getByRole('button',{name:'Generate',exact:true}).boundingBox();expect(box.x+box.width).toBeLessThanOrEqual(uploadBox.x);expect(uploadBox.x+uploadBox.width).toBeLessThanOrEqual(generateBox.x);expect(box.y+box.height/2).toBeCloseTo(uploadBox.y+uploadBox.height/2,0);expect(box.y).toBeLessThan(region.y+60);await page.screenshot({path:test.info().outputPath(`assets-top-link-${width}.png`),fullPage:true});const original=await link.evaluate(el=>({font:getComputedStyle(el).fontSize,height:el.getBoundingClientRect().height}));await link.click();await expect(page).toHaveURL(/assets\?folder=games%2Ftest-game%2F/);const back=page.getByRole('link',{name:'Back to assets',exact:true});await expect(back).toBeVisible();const backBox=await back.boundingBox(),headerBox=await page.locator('#explorer .explorer-heading').boundingBox();expect(backBox.x+backBox.width).toBeCloseTo(headerBox.x+headerBox.width,0);expect(await back.evaluate(el=>getComputedStyle(el).fontSize)).toBe(original.font);await back.click();await expect(page).toHaveURL(`${origin}/games/test-game/assets`);
});

