 const videoKey=assets[1].key,thumbnailKey=key('video-thumbnail');await context.route(`${api}/object-url?**`,route=>{const requested=new URL(route.request().url()).searchParams.get('key');if(requested===videoKey)return route.fulfill({json:{key:videoKey,contentType:'video/mp4',thumbnailKey},headers:{'access-control-allow-origin':origin}});if(requested===thumbnailKey)return route.fulfill({json:{key:thumbnailKey,contentType:'image/png',url:'https://media.example/video-thumbnail.png'},headers:{'access-control-allow-origin':origin}});return route.fallback();});await context.route('https://media.example/video-thumbnail.png',route=>route.fulfill({contentType:'image/png',body:Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Wl6ZQAAAABJRU5ErkJggg==','base64')}));
 await page.goto(`${origin}/games/test-game/assets`);const library=page.getByRole('region',{name:'Assets',exact:true});
 await expect(library.getByRole('button',{name:'Scout portrait Portrait · PNG',exact:true})).toBeVisible();await expect(library.getByRole('button',{name:'River crossing Video · MP4',exact:true})).toBeVisible();await expect(library).not.toContainText('Hidden provenance');
