for(const width of [1280,390])test(`Assets and Episodes share identical search controls at ${width}px`,async({page,context})=>{
 await page.setViewportSize({width,height:900});await fixture(page,context);
 const read=async section=>{await page.goto(`${origin}/games/test-game/${section}`);const form=page.locator('.library-search-filters');await expect(form).toBeVisible();const input=form.getByRole('searchbox');await expect(input).toBeVisible();return form.evaluate(el=>{const properties=['backgroundColor','color','height','borderRadius','borderColor','padding','fontSize'];const measure=node=>Object.fromEntries(properties.map(key=>[key,getComputedStyle(node)[key]]));const rect=el.getBoundingClientRect(),row=el.querySelector('.library-filter-fields').getBoundingClientRect(),search=el.querySelector('.library-search-field').getBoundingClientRect();return{input:measure(el.querySelector('input[type=search]')),tags:measure(el.querySelector('[data-multi-filter=tags] [role=combobox]')),characters:measure(el.querySelector('[data-multi-filter=characters] [role=combobox]')),formWidth:rect.width,rowWidth:row.width,searchWidth:search.width};});};
 const assets=await read('assets'),episodes=await read('episodes');for(const field of ['input','tags','characters'])expect(episodes[field]).toEqual(assets[field]);for(const state of [assets,episodes]){expect(state.rowWidth).toBeCloseTo(state.formWidth,0);expect(state.searchWidth).toBeCloseTo(state.formWidth,0);}
 await page.getByRole('searchbox',{name:'Search episodes'}).fill('missing');await expect(page.getByRole('searchbox',{name:'Search episodes'})).toHaveValue('missing');expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);
 await page.screenshot({path:test.info().outputPath(`shared-search-${width}.png`),fullPage:true});
});

async function openGenerate(page,type){const button=page.getByRole('button',{name:'Generate',exact:true});await button.click();await expect(page.getByRole('menu')).toBeVisible();await expect(page.getByRole('menuitem',{name:'3D',exact:true})).toHaveCount(0);await page.getByRole('menuitem',{name:type,exact:true}).click();}

for(const width of [1280,390])test(`Generate menu has a chevron and opens a typed dialog with keyboard at ${width}px`,async({page,context})=>{
 await page.setViewportSize({width,height:900});await fixture(page,context);await page.goto(`${origin}/games/test-game/assets`);
 const trigger=page.getByRole('button',{name:'Generate',exact:true});await expect(trigger.locator('.lucide-chevron-down')).toBeVisible();await trigger.focus();await page.keyboard.press('Enter');await expect(page.getByRole('menu')).toBeVisible();await expect(page.getByRole('menuitem',{name:'Map',exact:true})).toBeFocused();await page.keyboard.press('Enter');const dialog=page.getByRole('dialog',{name:'Generate Map',exact:true});await expect(dialog).toBeVisible();await expect(dialog.getByRole('combobox',{name:'Asset type',exact:true})).toHaveCount(0);await expect(dialog.getByRole('combobox',{name:'Model',exact:true})).toContainText('Image model');await page.keyboard.press('Escape');await expect(dialog).toHaveCount(0);await expect(trigger).toBeFocused();
});
